<script>
 import {onDestroy} from 'svelte';
 import {Sparkles,Upload,ArrowRight,Image} from 'lucide-svelte';
 let {kind='character',onsave,oncancel}=$props();
 let method=$state('generate'),name=$state(''),description=$state(''),appearance=$state(''),personality=$state(''),clothing=$state(''),actions=$state(''),emotions=$state(''),dialogue=$state(''),file=$state(null),error=$state(''),busy=$state(false),preview=$state('');
 onDestroy(()=>{if(preview)URL.revokeObjectURL(preview);});
 async function select(e){const next=e.currentTarget.files?.[0];if(!next)return;error='';if(next.name.toLowerCase().endsWith('.json')){try{if(next.size>2*1024*1024)throw Error('Choose a JSON file under 2 MB.');const d=JSON.parse(await next.text());if(!d||Array.isArray(d)||typeof d.name!=='string'&&typeof d.title!=='string')throw Error('Use one record with a name or title.');name=d.name||d.title;description=String(d.description||d.text||'');appearance=String(d.appearance||'');personality=String(d.personality||'');clothing=String(d.clothing||'');actions=String(d.actions||'');emotions=String(d.emotions||'');dialogue=String(d.dialogue||'');}catch(e){error=e.message;}return;}
 if(!['image/png','image/jpeg','image/webp'].includes(next.type)||next.size>20*1024*1024){error='Choose a PNG, JPEG or WebP under 20 MB.';return;}file=next;if(preview)URL.revokeObjectURL(preview);preview=URL.createObjectURL(next);if(!name)name=next.name.replace(/\.[^.]+$/,'').replace(/[-_]/g,' ');}
 async function save(){if(!name.trim()){error='Give this '+kind+' a name.';return;}if(method==='import'&&!file&&!description.trim()){error='Choose an image, import a JSON record, or describe the source you are importing.';return;}busy=true;error='';try{await onsave({kind,method,name:name.trim(),description:description.trim(),appearance,personality,clothing,actions,emotions,dialogue,file:method==='import'?file:null});}catch(e){error=e.message;}finally{busy=false;}}
</script>
<section class="asset-intake"><span class="eyebrow">YOUR STORY, YOUR MATERIAL</span><h2>Add a {kind}.</h2><p>Develop it here or bring an existing record and its visual reference.</p><div class="creation-methods"><button class:chosen={method==='generate'} onclick={()=>method='generate'}><Sparkles size={22}/><strong>Create / Generate</strong><span>Write a profile and prepare generation in the workspace.</span></button><button class:chosen={method==='import'} onclick={()=>method='import'}><Upload size={22}/><strong>Import your own</strong><span>Upload an image or a JSON record, then refine the details.</span></button></div>
 {#if method==='import'}<label class="pdf-drop"><Upload size={23}/><strong>{file?.name||'Choose an image or JSON record'}</strong><span>PNG, JPEG, WebP · or JSON with a name and description</span><input aria-label={'Upload '+kind} type="file" accept="image/png,image/jpeg,image/webp,.json,application/json" onchange={select}/></label>{#if preview}<img class="import-preview" src={preview} alt="Your selected visual reference"/>{/if}{/if}
 <label class="director-field">{kind==='scene'?'Scene title':'Name'}<input bind:value={name}/></label><label class="director-field">{kind==='scene'?'What happens in this moment':'Description'}<textarea bind:value={description}></textarea></label>
 {#if kind==='character'}<div class="import-field-grid"><label class="director-field">Appearance<textarea bind:value={appearance}></textarea></label><label class="director-field">Personality<textarea bind:value={personality}></textarea></label></div><label class="director-field">Clothing<textarea bind:value={clothing}></textarea></label>{:else if kind==='scene'}<label class="director-field">Actions<textarea bind:value={actions}></textarea></label><label class="director-field">Emotions<input bind:value={emotions}/></label><label class="director-field">Dialogue<textarea bind:value={dialogue}></textarea></label><p class="import-disclosure">Scenes below 100 words are saved as drafts. Connect characters and a location on the canvas before finalizing.</p>{/if}
 {#if method==='generate'}<p class="import-disclosure">Creating the record never makes a paid generation request. Review its prompt and explicitly choose Generate in the next step. Theme development uses your written direction; no language-model provider is connected.</p>{/if}
 {#if error}<p class="director-error" role="alert">{error}</p>{/if}<div class="form-actions"><button class="button secondary" onclick={oncancel} disabled={busy}>Cancel</button><button class="button primary" onclick={save} disabled={busy}>{busy?'Saving…':method==='import'?'Import & save':'Create & continue'}<ArrowRight size={15}/></button></div>
</section>
